}

/* SOURCE: src/windows/input.css — 米白胶囊输入框 */
#send_form {
    color: var(--mb-ink);
    border: 1.5px solid var(--mb-paper);
    border-radius: 26px;
    background-color: var(--mb-paper);
    background-image: var(--mb-paper-noise);
    background-size: 180px 180px;
    box-shadow: none;
    outline: 1px dashed var(--mb-dash);
    outline-offset: -6px;
    text-shadow: none;
}

#send_textarea {
    color: var(--mb-ink);
    border: 0;
    background: transparent;
    box-shadow: none;
    font-family: var(--mb-font-serif);
    text-shadow: none;
}

/* 官方占位字用 --SmartThemeEmColor 加 !important，这套主题的 EmColor 是米白，压在米白输入框上会看不见 */
#send_textarea::placeholder {
    color: rgba(13, 13, 15, 0.5) !important;
}

/* 官方是 #rightSendForm>div:not(.mes_stop), #leftSendForm>div（透明度 0.7），按同一选择器替换 */
#rightSendForm>div:not(.mes_stop),
#leftSendForm>div {
    color: var(--mb-ink);
    background: transparent;
    opacity: 1;
    filter: none;
    text-shadow: none;
}

@media (hover: hover) {
    #rightSendForm>div:hover,
    #leftSendForm>div:hover {
        color: var(--mb-mid);
        opacity: 1;
        filter: none;
    }
}

/* 发送键：墨黑圆章配米白纸飞机。圆用背景画，不改官方按钮的宽高；
 * 选择器要比上面那条更具体，否则底色会被 transparent 盖掉 */
#rightSendForm>#send_but:not(.mes_stop) {
    color: var(--mb-paper) !important;
    background: radial-gradient(circle, var(--mb-black) 0 15px, transparent 15.5px) center / 100% 100% no-repeat;
    font-size: 15px;
    transition: transform 0.2s ease;
}

#rightSendForm>#send_but:not(.mes_stop):active {
    transform: scale(0.88);
}

#mes_stop {
    color: var(--cl-danger);
}

#options,
#extensionsMenu {
    color: var(--mb-paper);
    border: 1.5px dashed var(--mb-dash-light);
    border-radius: 14px;
    background: #141416;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.55);
    text-shadow: none;
}

/* SOURCE: src/motion.css */
@keyframes mb-drop {
    from { opacity: 0; transform: translateY(14px); }
    to { opacity: 1; transform: none; }
}

#chat .mes.last_mes:not([is_system="true"]) {
    animation: mb-drop 0.5s cubic-bezier(0.2, 0.8, 0.3, 1.2) both;
}

body.reduced-motion #chat .mes,
body.reduced-motion #chat .mes .mesAvatarWrapper::before,
body.reduced-motion #chat .mes .mesAvatarWrapper::after,
body.reduced-motion #sheld::before,
body.reduced-motion #sheld::after {
    animation: none !important;
}

@media (prefers-reduced-motion: reduce) {
    #chat .mes,
    #chat .mes .mesAvatarWrapper::before,
    #chat .mes .mesAvatarWrapper::after,
    #sheld::before,
    #sheld::after {
        animation: none !important;
    }
}

.drawer-content :is(h2, h3, h4),
.popup :is(h2, h3, h4),
