/* SOURCE: src/windows/common.css
 * 抽屉、弹窗、表单：墨黑底 + 细颗粒，米白虚线外框；不改官方抽屉几何、显示或滚动
 */
.drawer-content {
    color: var(--mb-paper);
    border: 1.5px dashed var(--mb-dash-light);
    background-color: rgba(13, 13, 15, 0.99);
    background-image: var(--mb-grain);
    background-size: 5px 5px;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.55);
    text-shadow: none;
}

:is(.drawer-content, .popup, #options, #extensionsMenu)
    :is(input:not([type="range"]):not([type="checkbox"]):not([type="radio"]), textarea, select) {
    color: var(--mb-paper);
    border-color: var(--mb-line);
    background-color: #141416;
    font-family: var(--mb-font-ui);
    box-shadow: none;
}

/* Chromium 原生列表会脱离抽屉绘制，需精确覆盖 option */
select option,
select optgroup,
select option:not(:checked) {
    color: var(--mb-paper) !important;
    background-color: #141416 !important;
}

select option:checked {
    color: var(--mb-black) !important;
    background-color: var(--mb-paper) !important;
}

:is(.drawer-content, .popup, #options, #extensionsMenu)
    :is(input:not([type="range"]), textarea, select, button, .menu_button):disabled,
:is(.drawer-content, .popup, #options, #extensionsMenu) .disabled {
    color: rgba(242, 239, 232, 0.45);
    background-color: #141416;
    opacity: 0.7;
    filter: none;
    text-shadow: none;
}

.select2-container--default .select2-results__option {
    color: var(--mb-paper);
    background-color: #141416;
}

.select2-container--default .select2-results__option--highlighted,
.select2-container--default .select2-results__option[aria-selected="true"] {
    color: var(--mb-black);
    background-color: var(--mb-paper);
}

.select2-container--default .select2-selection--multiple,
.select2-container--default .select2-selection--single {
    color: var(--mb-paper);
    border-color: var(--mb-line);
    background-color: #141416;
}

.select2-container--default .select2-selection--multiple .select2-selection__choice {
    color: var(--mb-paper);
    border: 1px dashed var(--mb-dash-light);
    background-color: transparent;
}

:is(.drawer-content, .popup, #options, #extensionsMenu) :is(.menu_button, button) {
    color: var(--mb-paper);
    border-color: var(--mb-line-strong);
    border-radius: var(--cl-radius-sm);
    background-color: transparent;
    text-shadow: none;
}

/* 只在真正有鼠标悬停的设备上反色，手机点完不会一直亮着，免得和「已开启」分不清 */
@media (hover: hover) {
    :is(.drawer-content, .popup, #options, #extensionsMenu) :is(.menu_button, button):hover {
        color: var(--mb-black);
        border-color: var(--mb-paper);
        background-color: var(--mb-paper);
        filter: none;
    }
}

.drawer-content :is(h2, h3, h4),
.popup :is(h2, h3, h4) {
    color: var(--mb-paper);
    font-family: var(--mb-font-name);
